class DotnetWebWorkerClient {
    #worker;
    #pendingRequests = {};
    #requestId = 0;
    #defaultTimeout = 30000;

    constructor(worker) {
        this.#worker = worker;
    }

    static create() {
        return new Promise((resolve, reject) => {
            const worker = new Worker('_content/WebWorkerDemo/dotnet-web-worker.js', { type: "module" });

            worker.addEventListener('error', (e) => {
                reject(new Error(e.message || 'Worker encountered an error'));
            });

            worker.addEventListener('message', function onMessage(e) {
                if (e.data.type === "ready") {
                    worker.removeEventListener('message', onMessage);
                    if (e.data.error) {
                        reject(new Error(e.data.error));
                    } else {
                        const client = new DotnetWebWorkerClient(worker);
                        client.#setupMessageHandler();
                        resolve(client);
                    }
                }
            });
        });
    }

    invoke(method, args, timeout = this.#defaultTimeout) {
        return new Promise((resolve, reject) => {
            const id = ++this.#requestId;
            const timer = setTimeout(() => {
                this.#rejectRequest(id, "Request timeout");
            }, timeout);

            this.#pendingRequests[id] = { 
                resolve: r => {
                    clearTimeout(timer);
                    resolve(this.#parseIfJson(r));
                }, 
                reject: err => {
                    clearTimeout(timer);
                    reject(err);
                }
            };
            this.#worker.postMessage({ method, args, requestId: id });
        });
    }

    #parseIfJson(value) {
        if (typeof value === 'string') {
            try {
                return JSON.parse(value);
            } catch {
                return value;
            }
        }
        return value;
    }

    #rejectRequest(id, message) {
        const request = this.#pendingRequests[id];
        if (request) {
            request.reject(new Error(message));
            delete this.#pendingRequests[id];
        }
    }

    terminate() {
        this.#rejectAllPending("Worker terminated");
        this.#worker?.terminate();
        this.#worker = null;
    }

    #setupMessageHandler() {
        this.#worker.addEventListener('message', (e) => {
            if (e.data.type === "result") {
                const request = this.#pendingRequests[e.data.requestId];
                if (request) {
                    delete this.#pendingRequests[e.data.requestId];
                    if (e.data.error) {
                        request.reject(new Error(e.data.error));
                    } else {
                        request.resolve(e.data.result);
                    }
                }
            }
        });
    }

    #rejectAllPending(errorMessage) {
        for (const id in this.#pendingRequests) {
            this.#rejectRequest(id, errorMessage);
        }
    }
}

export function create() {
    return DotnetWebWorkerClient.create();
}

